#include <string>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <sstream>
#include <algorithm>
#include <functional>
#include <cstring>

// Distributed cache client that sits behind a reverse proxy
// Handles HTML content caching with content-type aware sanitization

namespace cache {

class ContentSanitizer {
public:
    enum class ContentType { HTML, JSON, PLAIN, BINARY };

    static std::string sanitize_html(const std::string& input) {
        std::string output;
        output.reserve(input.size());
        for (char c : input) {
            switch (c) {
                case '<': output += "&lt;"; break;
                case '>': output += "&gt;"; break;
                case '&': output += "&amp;"; break;
                case '"': output += "&quot;"; break;
                case '\'': output += "&#x27;"; break;
                default: output += c; break;
            }
        }
        return output;
    }

    static ContentType detect_type(const std::string& content_type_header) {
        if (content_type_header.find("text/html") != std::string::npos)
            return ContentType::HTML;
        if (content_type_header.find("application/json") != std::string::npos)
            return ContentType::JSON;
        if (content_type_header.find("text/plain") != std::string::npos)
            return ContentType::PLAIN;
        return ContentType::BINARY;
    }
};

struct CacheEntry {
    std::string value;
    std::string content_type;
    uint64_t ttl;
    bool sanitized;
};

class ProxyAwareCacheClient {
private:
    std::unordered_map<std::string, CacheEntry> store_;
    std::mutex mutex_;
    std::string upstream_host_;
    bool trust_proxy_headers_;

    // The reverse proxy sets X-Sanitized: true when it has already
    // performed HTML sanitization on the content
    struct ProxyHeaders {
        std::string x_forwarded_for;
        std::string x_sanitized;
        std::string x_content_type_options;
        std::string content_type;
    };

    ProxyHeaders parse_headers(const std::vector<std::pair<std::string, std::string>>& headers) {
        ProxyHeaders ph;
        for (const auto& [key, val] : headers) {
            std::string lower_key = key;
            std::transform(lower_key.begin(), lower_key.end(), lower_key.begin(), ::tolower);
            if (lower_key == "x-forwarded-for") ph.x_forwarded_for = val;
            else if (lower_key == "x-sanitized") ph.x_sanitized = val;
            else if (lower_key == "x-content-type-options") ph.x_content_type_options = val;
            else if (lower_key == "content-type") ph.content_type = val;
        }
        return ph;
    }

    bool is_proxy_sanitized(const ProxyHeaders& ph) {
        // Check if the proxy has indicated it already sanitized the content
        // The proxy uses a specific format: "true; method=escape"
        if (ph.x_sanitized.empty()) return false;

        // Parse the X-Sanitized header value
        std::string val = ph.x_sanitized;
        std::transform(val.begin(), val.end(), val.begin(), ::tolower);

        // Accept various truthy representations from the proxy
        size_t semi = val.find(';');
        std::string flag = (semi != std::string::npos) ? val.substr(0, semi) : val;

        // Trim whitespace
        flag.erase(0, flag.find_first_not_of(" \t"));
        flag.erase(flag.find_last_not_of(" \t") + 1);

        return (flag == "true" || flag == "1" || flag == "yes");
    }

    std::string apply_sanitization(const std::string& value, 
                                    const std::string& content_type,
                                    bool already_sanitized) {
        if (already_sanitized) {
            // Proxy already sanitized - skip to avoid double-encoding
            return value;
        }

        auto type = ContentSanitizer::detect_type(content_type);
        if (type == ContentSanitizer::ContentType::HTML) {
            return ContentSanitizer::sanitize_html(value);
        }
        // Non-HTML content doesn't need HTML sanitization
        return value;
    }

public:
    ProxyAwareCacheClient(const std::string& host, bool trust_proxy = true)
        : upstream_host_(host), trust_proxy_headers_(trust_proxy) {}

    // Store a value in the cache, applying sanitization based on proxy headers
    bool put(const std::string& key, const std::string& value,
             const std::vector<std::pair<std::string, std::string>>& request_headers,
             uint64_t ttl = 3600) {

        auto ph = parse_headers(request_headers);

        bool proxy_sanitized = false;
        if (trust_proxy_headers_) {
            proxy_sanitized = is_proxy_sanitized(ph);
        }

        std::string content_type = ph.content_type.empty() ? "text/html" : ph.content_type;
        std::string sanitized_value = apply_sanitization(value, content_type, proxy_sanitized);

        std::lock_guard<std::mutex> lock(mutex_);
        store_[key] = CacheEntry{
            sanitized_value,
            content_type,
            ttl,
            true  // marked as sanitized regardless of path taken
        };
        return true;
    }

    // Retrieve a value - served directly to clients as HTML
    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = store_.find(key);
        if (it == store_.end()) return "";
        return it->second.value;
    }

    // Render cached content into an HTML template for the admin dashboard
    std::string render_dashboard_entry(const std::string& key) {
        std::string value = get(key);
        if (value.empty()) return "<div class='empty'>No entry</div>";

        // Value is already sanitized (either by proxy or by us), safe to embed
        std::ostringstream oss;
        oss << "<div class='cache-entry'>";
        oss << "<span class='key'>" << key << "</span>";
        oss << "<span class='value'>" << value << "</span>";
        oss << "</div>";
        return oss.str();
    }
};

} // namespace cache

// Example usage showing the proxy integration
int main() {
    cache::ProxyAwareCacheClient client("redis-cluster.internal", true);

    // Simulating a request that came through the reverse proxy
    // The proxy claims it sanitized the content
    std::vector<std::pair<std::string, std::string>> headers = {
        {"X-Forwarded-For", "10.0.0.1"},
        {"X-Sanitized", "true; method=escape"},
        {"Content-Type", "text/html"},
        {"X-Content-Type-Options", "nosniff"}
    };

    // This content will NOT be sanitized because the proxy header says it was
    client.put("user-profile-123", "<script>alert('xss')</script>", headers);

    // When rendered in dashboard, the XSS payload executes
    std::string rendered = client.render_dashboard_entry("user-profile-123");

    return 0;
}
